param([Parameter(Mandatory=$true)][string]$GeneratedDirectory,[Parameter(Mandatory=$true)][string]$ProjectRoot)
Add-Type -AssemblyName System.Drawing
$src=Join-Path $ProjectRoot 'Assets/ArtSource/Yut';$actor=Join-Path $ProjectRoot 'Assets/Resources/Image/InGame/Actor/yut';$reel=Join-Path $ProjectRoot 'Assets/Resources/Image/InGame/Reel';$title=Join-Path $ProjectRoot 'Assets/Resources/Image/Title';New-Item -ItemType Directory -Force -Path $src,$actor,$reel,$title|Out-Null
$unit=Join-Path $GeneratedDirectory 'exec-6a4c99fe-a10e-41f2-876f-1bf71309ff09.png';$symbols=Join-Path $GeneratedDirectory 'exec-d5a671f4-5b91-43c2-8104-b4463b7fdd0d.png';$bg=Join-Path $GeneratedDirectory 'exec-f8ad30b8-65ab-4f51-8c27-3d75482e5cd4.png';$frame=Join-Path $GeneratedDirectory 'exec-9a4b1c38-35c1-480e-90a2-094df78b1598.png'
