function Load-Argb([string]$p){$a=[Drawing.Bitmap]::new($p);$b=[Drawing.Bitmap]::new($a.Width,$a.Height,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($b);$g.DrawImageUnscaled($a,0,0);$g.Dispose();$a.Dispose();return $b}
function Closest([Drawing.Color]$c,[Drawing.Color[]]$pal){$best=$pal[0];$score=[double]::MaxValue;foreach($p in $pal){$d=($c.R-$p.R)*($c.R-$p.R)+($c.G-$p.G)*($c.G-$p.G)+($c.B-$p.B)*($c.B-$p.B);if($d-lt$score){$score=$d;$best=$p}};return $best}
function Save-Cell([Drawing.Bitmap]$sheet,[Drawing.Rectangle]$cell,[string]$path,[int]$size,[bool]$blur){$work=[Drawing.Bitmap]::new($cell.Width,$cell.Height,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($work);$g.DrawImage($sheet,[Drawing.Rectangle]::new(0,0,$cell.Width,$cell.Height),$cell,[Drawing.GraphicsUnit]::Pixel);$g.Dispose();$minX=$work.Width;$minY=$work.Height;$maxX=-1;$maxY=-1
for($y=0;$y-lt$work.Height;$y++){for($x=0;$x-lt$work.Width;$x++){$c=$work.GetPixel($x,$y);$v=($c.R+$c.G+$c.B)/3;if($c.A-lt10-or($v-gt28-and$v-lt105)){$work.SetPixel($x,$y,[Drawing.Color]::Transparent);continue};if(-not$blur){if($v-ge205){$q=[Drawing.Color]::FromArgb(255,246,245,240)}elseif($v-ge105){$q=[Drawing.Color]::FromArgb(255,173,172,164)}else{$q=[Drawing.Color]::FromArgb(255,42,44,51)};$work.SetPixel($x,$y,$q)};if($work.GetPixel($x,$y).A-gt10){if($x-lt$minX){$minX=$x};if($x-gt$maxX){$maxX=$x};if($y-lt$minY){$minY=$y};if($y-gt$maxY){$maxY=$y}}}}
$crop=[Drawing.Rectangle]::new($minX,$minY,$maxX-$minX+1,$maxY-$minY+1);$scale=[Math]::Min(($size-6)/$crop.Width,($size-6)/$crop.Height);$w=[int][Math]::Round($crop.Width*$scale);$h=[int][Math]::Round($crop.Height*$scale);$out=[Drawing.Bitmap]::new($size,$size,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($out);$g.Clear([Drawing.Color]::Transparent);$g.InterpolationMode=if($blur){[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic}else{[Drawing.Drawing2D.InterpolationMode]::NearestNeighbor};$g.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::Half;$g.DrawImage($work,[Drawing.Rectangle]::new([int](($size-$w)/2),[int](($size-$h)/2),$w,$h),$crop,[Drawing.GraphicsUnit]::Pixel);$g.Dispose();$work.Dispose();$out.Save($path,[Drawing.Imaging.ImageFormat]::Png);$out.Dispose()}
$names=@('yut_00_backdo','yut_01_do','yut_02_gae','yut_03_geol','yut_04_yut','yut_05_mo');$sheet=Load-Argb $symbols;$cw=[int][Math]::Floor($sheet.Width/6);$ch=[int][Math]::Floor($sheet.Height/2);for($i=0;$i-lt6;$i++){Save-Cell $sheet ([Drawing.Rectangle]::new($i*$cw,0,$cw,$ch)) (Join-Path $actor ($names[$i]+'.png')) 32 $false;Save-Cell $sheet ([Drawing.Rectangle]::new($i*$cw,$ch,$cw,$ch)) (Join-Path $actor ($names[$i]+'_blur.png')) 32 $true;$base=[Drawing.Bitmap]::new((Join-Path $actor ($names[$i]+'.png')));$x8=[Drawing.Bitmap]::new(256,256,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($x8);$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::Half;$g.DrawImage($base,[Drawing.Rectangle]::new(0,0,256,256));$g.Dispose();$base.Dispose();$x8.Save((Join-Path $actor ($names[$i]+'_x8.png')),[Drawing.Imaging.ImageFormat]::Png);$x8.Dispose()};$sheet.Dispose()
$units=Load-Argb $unit;$uw=[int][Math]::Floor($units.Width/4);$uh=[int][Math]::Floor($units.Height/2);Save-Cell $units ([Drawing.Rectangle]::new(2*$uw,$uh,$uw,$uh)) (Join-Path $src 'yut_backdo_special_preview.png') 256 $false;$units.Dispose()
function Save-Pal([string]$ip,[string]$op,[int]$w,[int]$h,[Drawing.Color[]]$pal,[bool]$transparentWhite){$input=Load-Argb $ip;$out=[Drawing.Bitmap]::new($w,$h,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($out);$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::Half;$g.DrawImage($input,[Drawing.Rectangle]::new(0,0,$w,$h));$g.Dispose();$input.Dispose();for($y=0;$y-lt$h;$y++){for($x=0;$x-lt$w;$x++){$c=$out.GetPixel($x,$y);if($c.A-lt10-or($transparentWhite-and$c.R-gt225-and$c.G-gt225-and$c.B-gt225)){$out.SetPixel($x,$y,[Drawing.Color]::Transparent)}else{$out.SetPixel($x,$y,(Closest $c $pal))}}};$out.Save($op,[Drawing.Imaging.ImageFormat]::Png);$out.Dispose()}
$fp=@('#363B4A','#393E4E','#454B5E','#585F74','#707892','#828CA6')|%{[Drawing.ColorTranslator]::FromHtml($_)};$bp=@('#486B41','#57A277','#58734A','#635C4D','#68854B','#6E9CB4','#72956A','#766E5C','#7C8896','#7FA391','#847357','#8A8270','#8FB6C0','#93B0A6','#94A0AC','#94B4A0','#9A9279','#A6B0BA','#A6C0B4','#A79E86','#BBD3CC','#CFE0D8','#F0F5F2')|%{[Drawing.ColorTranslator]::FromHtml($_)};Save-Pal $frame (Join-Path $reel 'frame_yut.png') 136 260 $fp $true;Save-Pal $bg (Join-Path $title 'bg_yut_folkvillage.png') 640 288 $bp $false
